"use server"

import { revalidatePath } from "next/cache"
import { redirect } from "next/navigation"

let notificationPreference = false

// Server Action to toggle notification preference
export async function toggleNotification() {
  notificationPreference = !notificationPreference

  // Revalidate the current page to show updated preference
  revalidatePath("/")

  // Redirect back to the current page to refresh
  redirect("/")
}

export function getNotificationPreference() {
  return notificationPreference
}

