input.newString:
import { toggleNotification, getNotificationPreference } from "./actions/notification"

export default async function Home() {
  const notificationPreference = await getNotificationPreference()

  return (
    <main>
      <h1>Settings</h1>
      <p>Notification preference: {notificationPreference ? "ON" : "OFF"}</p>
      <form action={toggleNotification}>
        <button type="submit">Toggle Notification</button>
      </form>
    </main>
  );
}

